    (fun R M => PMSA.a0 R V /\ True /\ sp mod 32 = 0 /\ PMSA.stksh ar M sp (PMESA.VIS_SCRA 12800) /\ PMESA.enc_invA L IC EC M V S2 g /\ ev_guard (g_es g) (EvBegin false) /\
                PMESA.eroomA CL g (EvBegin false) /\ PMLA.img_ro IC M /\ PMESA.lits_ok L IC M /\ PMESA.ecreditA L CL cr g kx bx /\
